-- FleetPilot SQLite schema (node:sqlite). Applied automatically by db.js on startup.
-- Dates are TEXT 'YYYY-MM-DD', times TEXT 'HH:MM:SS', money REAL, booleans INTEGER 0/1.

-- IDs are generated by the app (db.nextId), so they are NOT auto-increment.

CREATE TABLE IF NOT EXISTS vehicles (
  id        INTEGER NOT NULL PRIMARY KEY,
  reg       TEXT    NOT NULL DEFAULT '',
  make      TEXT    NOT NULL DEFAULT '',
  model     TEXT    NOT NULL DEFAULT '',
  year      TEXT    NOT NULL DEFAULT '',
  rate      REAL    NOT NULL DEFAULT 0,
  owner     TEXT    NOT NULL DEFAULT '',
  status    TEXT    NOT NULL DEFAULT 'Available'  -- Available | Rented | Maintenance | Inactive
);
CREATE INDEX IF NOT EXISTS idx_vehicles_reg ON vehicles (reg);
CREATE INDEX IF NOT EXISTS idx_vehicles_status ON vehicles (status);

CREATE TABLE IF NOT EXISTS drivers (
  id         INTEGER NOT NULL PRIMARY KEY,
  name       TEXT    NOT NULL DEFAULT '',
  phone      TEXT    NOT NULL DEFAULT '',
  license    TEXT    NOT NULL DEFAULT '',
  vehicle_id INTEGER NULL REFERENCES vehicles(id) ON DELETE SET NULL,
  allowance  REAL    NOT NULL DEFAULT 0,
  status     TEXT    NOT NULL DEFAULT ''
);

CREATE TABLE IF NOT EXISTS clients (
  id     INTEGER NOT NULL PRIMARY KEY,
  name   TEXT    NOT NULL DEFAULT '',
  phone  TEXT    NOT NULL DEFAULT '',
  idnum  TEXT    NOT NULL DEFAULT '',   -- national ID / passport
  dl     TEXT    NOT NULL DEFAULT ''    -- driving licence
);
CREATE INDEX IF NOT EXISTS idx_clients_name ON clients (name);

CREATE TABLE IF NOT EXISTS bookings (
  id           INTEGER NOT NULL PRIMARY KEY,
  vehicle_id   INTEGER NULL REFERENCES vehicles(id) ON DELETE SET NULL,
  client_id    INTEGER NULL REFERENCES clients(id)  ON DELETE SET NULL,
  booked_on    TEXT    NULL,
  pickup_date  TEXT    NULL,
  return_date  TEXT    NULL,
  deposit      REAL    NOT NULL DEFAULT 0,
  status       TEXT    NOT NULL DEFAULT 'Pending',   -- Pending | Confirmed | Cancelled ...
  reminder_ack INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS idx_bookings_pickup ON bookings (pickup_date);

CREATE TABLE IF NOT EXISTS rentals (
  id           INTEGER NOT NULL PRIMARY KEY,
  vehicle_id   INTEGER NULL REFERENCES vehicles(id) ON DELETE SET NULL,
  client_id    INTEGER NULL REFERENCES clients(id)  ON DELETE SET NULL,
  contract     TEXT    NOT NULL DEFAULT '',
  invoice      TEXT    NOT NULL DEFAULT '',
  receipt      TEXT    NOT NULL DEFAULT '',
  pickup_date  TEXT    NULL,
  pickup_time  TEXT    NULL,
  return_date  TEXT    NULL,
  return_time  TEXT    NULL,
  rate         REAL    NOT NULL DEFAULT 0,
  days         REAL    NOT NULL DEFAULT 0,
  mileage      TEXT    NOT NULL DEFAULT '',
  amount       REAL    NOT NULL DEFAULT 0,
  status       TEXT    NOT NULL DEFAULT 'Active',  -- Active | Completed | Cancelled
  fuel         REAL    NOT NULL DEFAULT 0,
  fuel_charge  REAL    NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS idx_rentals_status ON rentals (status);
CREATE INDEX IF NOT EXISTS idx_rentals_pickup ON rentals (pickup_date);
CREATE INDEX IF NOT EXISTS idx_rentals_vehicle ON rentals (vehicle_id);

CREATE TABLE IF NOT EXISTS expenses (
  id             INTEGER NOT NULL PRIMARY KEY,
  vehicle_id     INTEGER NULL REFERENCES vehicles(id) ON DELETE SET NULL,
  expense_date   TEXT    NULL,
  category       TEXT    NOT NULL DEFAULT '',
  description    TEXT    NOT NULL DEFAULT '',
  qty            REAL    NOT NULL DEFAULT 1,
  amount         REAL    NOT NULL DEFAULT 0,
  billable       INTEGER NOT NULL DEFAULT 0,
  bill_client_id INTEGER NULL REFERENCES clients(id) ON DELETE SET NULL,
  charge_amount  REAL    NOT NULL DEFAULT 0,
  source         TEXT    NOT NULL DEFAULT 'manual',  -- manual | rental
  rental_id      INTEGER NULL REFERENCES rentals(id) ON DELETE SET NULL
);
CREATE INDEX IF NOT EXISTS idx_expenses_date ON expenses (expense_date);
CREATE INDEX IF NOT EXISTS idx_expenses_category ON expenses (category);

CREATE TABLE IF NOT EXISTS payments (
  id           INTEGER NOT NULL PRIMARY KEY,
  rental_id    INTEGER NULL REFERENCES rentals(id) ON DELETE SET NULL,
  payment_date TEXT    NULL,
  amount       REAL    NOT NULL DEFAULT 0,
  method       TEXT    NOT NULL DEFAULT '',
  note         TEXT    NOT NULL DEFAULT ''
);
CREATE INDEX IF NOT EXISTS idx_payments_date ON payments (payment_date);

CREATE TABLE IF NOT EXISTS driver_allowances (
  id         INTEGER NOT NULL PRIMARY KEY,
  driver_id  INTEGER NULL REFERENCES drivers(id) ON DELETE SET NULL,
  week_start TEXT    NULL,
  amount     REAL    NOT NULL DEFAULT 0,
  note       TEXT    NOT NULL DEFAULT ''
);

-- Single-row table: settings, id counter, period and sync metadata.
CREATE TABLE IF NOT EXISTS app_state (
  id             INTEGER NOT NULL PRIMARY KEY DEFAULT 1 CHECK (id = 1),
  settings       TEXT    NULL,   -- JSON
  next_id        INTEGER NOT NULL DEFAULT 1,
  period         TEXT    NULL,   -- JSON
  last_modified  TEXT    NULL,
  file_name      TEXT    NULL,
  workbook_dirty INTEGER NOT NULL DEFAULT 1,
  revision       INTEGER NOT NULL DEFAULT 0,
  saved_at       TEXT    NULL    -- ISO-8601 UTC
);

INSERT OR IGNORE INTO app_state (id, next_id, revision) VALUES (1, 1, 0);
